import logging

from taf.fdsw.rc.interfaces.FDSW20B.diagnostics import Diagnostics20B

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())
logging.basicConfig(level=logging.INFO)


class Diagnostics23B(Diagnostics20B):

    def download_ssh_activity_log(self, path, timeout):
        endpoint = 'diagnostics.ssh.download'
        return self._client.download_autoconfiguration_report(endpoint, path, timeout)
